export function solve(value: number): number {
  return String(value);
}

export function solve(profile: { name: string } | null): string {
  return profile.name;
}

import { twice } from './missing.js';
export function solve(value: number): number {
  return twice(value);
}

export function solve(values: number[]): number | undefined {
  return values[values.length];
}

export function solve(values: number[]): number[] {
  return [...values].sort();
}

export function solve(value: number | undefined): number {
  return value || 10;
}

export function solve(price: number): number {
  return Math.floor(price * 100);
}

export function solve(values: number[]): number[] {
  return values.map(value => { value * 2; });
}

export function solve(values: number[]): number[] {
  return values.filter(value => value < 0);
}

export async function solve(): Promise<number> {
  const value = Promise.resolve(7);
  return value + 1;
}

export function solve(values: number[] | undefined): number {
  return values.reduce((total, value) => total + value, 0);
}

export function solve(values: number[]): number[] {
  return values.sort((left, right) => left - right);
}
